class Solution {
public:
    vector<vector<char>> rotateTheBox(vector<vector<char>>& box) {
        int m = box.size(), n = box[0].size();
        for (int r = 0; r < m; ++r) {
            int emptySlot = n - 1;
            for (int c = n - 1; c >= 0; --c) {
                if (box[r][c] == '*') {
                    emptySlot = c - 1;
                } else if (box[r][c] == '#') {
                    box[r][c] = '.';
                    box[r][emptySlot] = '#';
                    emptySlot--;
                }
            }
        }

        vector<vector<char>> rotated(n, vector<char>(m));
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                rotated[c][m - 1 - r] = box[r][c];
            }
        }
        return rotated;
    }
};

