var rotateTheBox = function(box) {
    const m = box.length, n = box[0].length;
    for (let r = 0; r < m; ++r) {
        let emptySlot = n - 1;
        for (let c = n - 1; c >= 0; --c) {
            if (box[r][c] === '*') {
                emptySlot = c - 1;
            } else if (box[r][c] === '#') {
                box[r][c] = '.';
                box[r][emptySlot] = '#';
                emptySlot--;
            }
        }
    }

    const rotated = Array.from({ length: n }, () => Array(m));
    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            rotated[c][m - 1 - r] = box[r][c];
        }
    }
    return rotated;
};
